mapper.select:
/* DayTimeSaleBensonMapper.getDayTimeSaleBensonList */
SELECT
TO_CHAR(TO_DATE(tsdt.SALE_DATE, 'yyyymmdd'), 'yyyy-mm-dd') AS SALE_DATE,
TO_CHAR(TO_DATE(tsdt.SALE_DATE, 'YYYYMMDD'), 'DY') AS YOIL,
SUM(tsdt.REAL_SALE_AMT) AS REAL_SALE_AMT_TOT,

    SUM(CASE WHEN tsdt.SALE_HOUR = #{item} THEN tsdt.REAL_SALE_AMT ELSE 0 END) AS REAL_SALE_AMT${item}

FROM TB_SL_DAILY_TIME tsdt
WHERE 1=1
AND tsdt.HQ_OFFICE_CD = #{hqOfficeCd}
AND tsdt.STORE_CD = #{storeCd}
AND tsdt.SALE_DATE BETWEEN #{startDate} AND #{endDate}
AND tsdt.SALE_HOUR BETWEEN #{startTime} AND #{endTime}
GROUP BY tsdt.SALE_DATE
ORDER BY tsdt.SALE_DATE DESC
